import sys,json,ast,re,pathlib
for p in sys.argv[1:]:
    b=pathlib.Path(p).read_bytes()
    binary=(b.find(b\"\\0\")>=0)
    s=b.decode(\"utf-8\",\"replace\")
    lines=s.splitlines()
    out={\"p\":p,\"n\":len(lines),\"binary\":binary,\"doc\":\"\",\"defs\":[],\"alls\":[],\"imports\":[],\"froms\":[],\"rules\":[],\"tests\":[],\"first\":\"\"}
    clean=[]
    for line in lines:
        x=line.strip().lstrip(\"\\ufeff\")
        if x and not re.fullmatch(r\"[-=~"'^_*+#.:/'"\\\\ ]{3,}\",x):
            clean.append(re.sub(r\"\\s+\",\" \",x))
    out[\"first\"]=(clean[0][:220] if clean else \"\")
    if p.endswith(\".py\"):
        try:
            t=ast.parse(s)
            d=ast.get_docstring(t,clean=False) or \"\"
            out[\"doc\"]=re.sub(r\"\\s+\",\" \",d).strip()[:500]
            for node in t.body:
                if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):
                    out[\"defs\"].append([node.name,\"class\" if isinstance(node,ast.ClassDef) else \"function\"])
                elif isinstance(node,ast.Assign):
                    if any(isinstance(z,ast.Name) and z.id==\"__all__\" for z in node.targets):
                        try:
                            v=ast.literal_eval(node.value)
                            if isinstance(v,(list,tuple)): out[\"alls\"]=[str(x) for x in v if isinstance(x,str)]
                        except Exception: pass
                elif isinstance(node,ast.Import):
                    for a in node.names: out[\"imports\"].append(a.name)
                elif isinstance(node,ast.ImportFrom):
                    mod=node.module or \"\"
                    if node.level:
                        parts=p.split(\"/\")[:-1]
                        base=parts[:max(1,len(parts)-node.level+1)]
                        mod=\".\".join(base+([mod] if mod else []))
                    out[\"imports\"].append(mod)
                    out[\"froms\"] += [a.asname or a.name for a in node.names if a.name"'!="*"]
            out["tests"]=[n for n,k in out["defs"] if n.startswith("test")]
        except Exception:
            pass
    else:
        m=re.search(r"/'"\\*+[\\s"'!*]*(.*?)(?:'"\\*/)\",s,re.S)
        if m: out[\"doc\"]=re.sub(r\"\\s+\",\" \",re.sub(r\""'^[ '"\\t]*\\* ?\",\"\",m.group(1),flags=re.M)).strip()[:500]
        names=re.findall(r\"(?m)"'^(?:cdef|cpdef|def)'"\\s+(?:\\w+\\s+)*(\\w+)\\s*\\(|"'^(?:[A-Za-z_]'"\\w*(?:\\s+|\\s*\\*+\\s*)){1,4}([A-Za-z_]\\w*)\\s*\\(["'^;{}]*'"\\)\\s*\\{\",s)
        out[\"defs\"]=[[a or z,\"function\"] for a,z in names[:30]]
        for a,z in re.findall(r\"(?m)"'^'"\\s*(?:from\\s+([\\w.]+)\\s+)?c?import\\s+([\\w.]+)\",s):
            out[\"imports\"].append(a or z)
    for m in re.finditer(r\"(?im)"'^[ '"\\t]*(?:#|//|\\*)[ \\t]*(.{0,220}\\b(?:must|should|shall|required|do not|never|only|warning|note)\\b.{0,220})\",s):
        x=re.sub(r\"\\s+\",\" \",m.group(1)).strip()
        if x and x not in out[\"rules\"]: out[\"rules\"].append(x[:260])
        if len(out[\"rules\"])>=3: break
    print(json.dumps(out,ensure_ascii=False))
