/bin/bash -lc "python -c '
import sys,json,ast,re,pathlib
for p in sys.argv[1:]:
 b=pathlib.Path(p).read_bytes();binary=(b.find(b\"\\0\")>=0);s=b.decode(\"utf-8\",\"replace\");lines=s.splitlines();o={\"p\":p,\"n\":len(lines),\"binary\":binary,\"doc\":\"\",\"defs\":[],\"alls\":[],\"imports\":[],\"froms\":[],\"rules\":[],\"first\":\"\"}
 c=[]
 for line in lines:
  x=line.strip().lstrip(\"\\ufeff\")
  if x and not re.fullmatch(r\"[-=~"'^_*+#.:/'"\\\\ ]{3,}\",x):c.append(re.sub(r\"\\s+\",\" \",x))
 o[\"first\"]=c[0][:220] if c else \"\"
 if not binary and p.endswith(\".py\"):
  try:
   t=ast.parse(s);d=ast.get_docstring(t,clean=False) or \"\";o[\"doc\"]=re.sub(r\"\\s+\",\" \",d).strip()[:500]
   for n in t.body:
    if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):o[\"defs\"].append([n.name,\"class\" if isinstance(n,ast.ClassDef) else \"function\"])
    elif isinstance(n,ast.Assign) and any(isinstance(z,ast.Name) and z.id==\"__all__\" for z in n.targets):
     try:
      v=ast.literal_eval(n.value)
      if isinstance(v,(list,tuple)):o[\"alls\"]=[str(z) for z in v if isinstance(z,str)]
     except:pass
    elif isinstance(n,ast.Import):
     for a in n.names:o[\"imports\"].append(a.name)
    elif isinstance(n,ast.ImportFrom):
     mod=n.module or \"\"
     if n.level:
      parts=p.split(\"/\")[:-1];base=parts[:max(1,len(parts)-n.level+1)];mod=\".\".join(base+([mod] if mod else []))
     o[\"imports\"].append(mod);o[\"froms\"] += [a.asname or a.name for a in n.names if a.name"'!="*"]
  except:pass
 elif not binary and re.search(r"'"\\.(?:pyx|pxd|c|h|l)"'$",p):
  m=re.search(r"/'"\\*+[\\s"'!*]*(.*?)(?:'"\\*/)\",s,re.S)
  if m:o[\"doc\"]=re.sub(r\"\\s+\",\" \",re.sub(r\""'^[ '"\\t]*\\* ?\",\"\",m.group(1),flags=re.M)).strip()[:500]
  ns=re.findall(r\"(?m)"'^(?:cdef|cpdef|def)'"\\s+(?:\\w+\\s+)*(\\w+)\\s*\\(|"'^(?:[A-Za-z_]'"\\w*(?:\\s+|\\s*\\*+\\s*)){1,4}([A-Za-z_]\\w*)\\s*\\(["'^;{}]*'"\\)\\s*\\{\",s);o[\"defs\"]=[[a or z,\"function\"] for a,z in ns[:30]]
  for a,z in re.findall(r\"(?m)"'^'"\\s*(?:from\\s+([\\w.]+)\\s+)?c?import\\s+([\\w.]+)\",s):o[\"imports\"].append(a or z)
 if not binary:
  for m in re.finditer(r\"(?im)"'^[ '"\\t]*(?:#|//|\\*)[ \\t]*(.{0,220}\\b(?:must|should|shall|required|do not|never|only|warning|note)\\b.{0,220})\",s):
   x=re.sub(r\"\\s+\",\" \",m.group(1)).strip()
   if x and x not in o[\"rules\"]:o[\"rules\"].append(x[:260])
   if len(o[\"rules\"])>=3:break
